                            + `\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias`
                            + `\n\`💸\` **Total**: R$${totalAmount}`
                        ),

                    new EmbedBuilder()
                        .setDescription("- **Pague o Pix via QR CODE ou código pix abaixo**\n- O pagamento será verificado automaticamente\n- Expira em <t::R>")
                        .setImage(`attachment://qrcode.png`)
                ],
