```js
const { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, ComponentType } = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');

const crypto = require('crypto');
const { Cart, Payment } = require('../database/models/Models');

// ------------------------------------------------------------------
// Configurações globais (ajuste conforme seu ambiente)
// ------------------------------------------------------------------
class CartClass {
    /** @type {'mensal'|'quizena'|'semanal'} */
    #currentPlan = null;
    /** @type {number} dias correspondentes ao plano */
    #days = 0;
    /** @type {string} ID único do carrinho */
    #cartId = '';
    /** @type {Discord.GuildChannel|null} canal/thread do carrinho */
    #channel = null;
    /** @type {number} quantidade do produto */
    #quantity = 1;
    /** @type {boolean} flag de inatividade ativa */
    #inactivityActive = false;
    /** @type {NodeJS.Timeout|null} timer de inatividade */
    #inactivityTimer = null;
    /** @type {number} delay em ms entre checks de pagamento */
    #paymentCheckIntervalMs = 60_000;
    /** @type {number} delay padrão de inatividade (ms) */
    #inactivityDelayMs = 10 * 60 * 1000; // 10 minutos
    /** @type {string} ID do cargo de "comprador aprovado" */
    #approvedRoleId = null;
    /** @type {string} URL de notificação do Payment Processor */
    #notificationUrl = '';

    /**
     * Cria uma instância de CartClass
     * @param {Discord.Client} client
     * @param {Discord.Interaction|string|null} interaction - interação original ou null quando usada internamente
     * @param {string} productId - ID do produto
     * @param {Object} productData - dados do produto (preco.mensal, .quizena, .semanal)
     * @param {string|Discord.User} user - usuário comprador
     */
    constructor(client, interaction, productId, productData, user) {
        this.client = client;
        /** @type {Discord.Interaction|null} */
        this.interaction = typeof interaction === 'string' || interaction instanceof String
            ? null
            : interaction;

        this.productId = productId;
        this.productData = productData;

        /** @type {Discord.User|null} */
        const resolvedUser = interaction?.user || (typeof user === 'string' && client.users.cache.has(user) ? client.users.cache.get(user) : user);
        this.user = resolvedUser ?? interaction?.client?.users?.cache?.get(String(user));

        if (!this.user) throw new Error('Usuário inválido.');

        this.paymentProcessor = new PaymentProcessor();
        this.#inactivityActive = false;
        this.#cartId = crypto.randomBytes(12).toString('hex');
        this.#channel = null;
        this.#quantity = 1;
        this.#selectedPlan = null; // mantém referência pública simples
        this.#messageId = null;

        // Carrega configuração global (pode vir de env, config.yaml, etc.)
        this.#approvedRoleId = process.env.APPROVED_ROLE_ID || '995154994183548953';
        this.#notificationUrl = process.NOTIFICATION_URL || 'https://nyox.tech/api/notifications';

        console.log(`[CartClass] Carrinho criado para ${this.user.username} (${this.user.id}) — produto: ${productId}`);
    }

    // ---------------------------------------------------------------
    // Helpers internos
    // ---------------------------------------------------------------

    /**
     * Define o plano/dias a partir do valor de `plan`.
     * @param {'mensal'|'quizena'|'semanal'} plan
     */
    setPlan(plan) {
        if (!['mensal', 'quizena', 'semanal'].includes(plan)) return;
        this.#currentPlan = plan;
        switch (plan) {
            case 'mensal':   this.#days = 30; break;
            case 'quizena':  this.#days = 15; break;
            case 'semanal':  this.#days = 7;  break;
            default:         this.#days = 0;  break;
        }
        console.log(`[CartClass] Plano alterado para ${plan} (${this.#days} dias)`);
    }

    /**
     * Envia um log estruturado para o canal configurado.
     * @param {string} topic
     * @param {object} [fields]
     */
    async sendLog(topic = 'Sistema', fields = {}) {
        const logChannelId = '1264758034979360860'; // 🔴 substitua pelo ID real
        if (!logChannelId) return;

        const logChannel = this.client.channels.cache.get(logChannelId);
        if (!logChannel) return;

        const timestamp = `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`;
        const data = { ...fields, timestamp };
        const embed = new EmbedBuilder()
            .setTitle(`📝 Log — ${topic}`)
            .setColor('#FF4500')
            .addFields(...Object.entries(data).map(([k, v]) => ({ name: k, value: String(v), inline: k.startsWith('🕒') })))
            .setFooter({ text: this.client.user.username });

        await logChannel.send({ embeds: [embed] });
    }

    /**
     * Limpa todos os intervalos de checagem de pagamento deste carrinho.
     */
    clearPaymentCheck() {
        if (this.#paymentCheckIntervalId) {
            clearInterval(this.#paymentCheckIntervalId);
            this.#paymentCheckIntervalId = null;
        }
    }

    // ---------------------------------------------------------------
    // Métodos públicos
    // ---------------------------------------------------------------

    /**
     * Abre/retoma um carrinho existente ou cria um novo.
     * @returns {Promise<boolean>}
     */
    async createOrOpenCart() {
        try {
            // 1) Verifica carrinho ativo do mesmo usuário
            const existing = await Cart.findOne({ userId: this.user.id, status: { $ne: null } });
            if (existing) {
                this.#channel = existing.channelId ? this.client.channels.cache.get(existing.channelId) : null;
                if (this.#channel) {
                    this.#cartId = existing.id;
                    this.#quantity = existing.quantity || 1;
                    this.#currentPlan = existing.selectedPlan || 'mensal';
                    this.#days = this.#currentPlan === 'mensal' ? 30
                        : this.#currentPlan === 'quizena' ? 15
                        : 7;
                    console.log(`[CartClass] Carrinho retomado: ${existing.id}`);
                    return this._showExistingCart();
                }
            }

            // 2) Não há carrinho ativo → criar novo
            await this.interaction?.reply?.({ content: 'Aguarde um momento… estou preparando seu carrinho.', ephemeral: true })
                .catch(() => {});

            const thread = await this.interaction?.channel?.threads?.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho — ${this.productData.productName} — #${this.#cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: 'Criação de carrinho de compras',
                members: [this.user.id],
                permissionOverwrites: [
                    { id: this.user.id, allow: ['ViewChannel'], deny: ['SendMessages'] },
                    { id: this.interaction.guild.id, deny: ['ViewChannel', 'SendMessages'] }
                ]
            });

            if (!thread) throw new Error('Falha ao criar thread do carrinho.');

            this.#channel = thread;

            // Persiste no banco
            await Cart.upsert({
                _id: this.#cartId,
                channelId: this.#channel.id,
                userId: this.user.id,
                quantity: this.#quantity,
                productId: this.productId,
                selectedPlan: this.#currentPlan,
                days: this.#days,
                status: 'Aguardando...',
                paymentId: null,
                createdAt: Date.now(),
            }, { upsert: true, documentOtherKeys: true });

            // Define timer de inatividade
            this.#startInactivityTimer();

            // Mostra embed inicial + botão de seleção de plano
            const initialEmbed = this._buildPlanSelectionEmbed();
            this.#messageId = await this.#channel.send(initialEmbed);

            // Já dispara seleção padrão (30 dias)
            await this._handlePlanSelection(null, '30DiasCart');

            console.log(`[CartClass] Carrinho aberto: ${this.#channel.id}`);
            return true;

        } catch (error) {
            console.error('[CartClass] Erro ao criar/abrir carrinho:', error.message);
            return false;
        }
    }

    /**
     * Mostra o embed indicando que o carrinho já existe.
     * @private
     */
    _showExistingCart() {
        const guild = this.client.guilds.cache.has(this.interaction?.guildId) ? this.interaction.guild : null;
        const channelUrl = this.#channel?.url ?? '';

        const reply = {
            content: `Você já tem um carrinho ativo!`,
            ephemeral: true,
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setStyle(ButtonStyle.Link)
                        .setLabel('Voltar ao Carrinho')
                        .setURL(channelUrl)
                )
            ]
        };

        if (this.interaction) {
            this.interaction.reply(reply);
        }
    }

    /**
     * Build do embed de seleção de planos.
     * @private
     */
    _buildPlanSelectionEmbed() {
        const { preco } = this.productData;
        const fields = [];

        const plans = [
            { key: 'mensal',   emoji: '📅', label: '30 Dias', customId: '30DiasCart' },
            { key: 'quizena',  emoji: '🗓️', label: '15 Dias', customId: '15DiasCart' },
            { key: 'semanal',  emoji: '📆', label: '7 Dias',  customId: '7DiasCart' },
        ];

        for (const p of plans) {
            if (preco[p.key]?.onoff) {
                fields.push({
                    name: `${p.emoji} ${p.label}`,
                    value: `**${p.key === 'mensal' ? 'Mensal' : p.key === 'quizena' ? 'Quinzenal' : 'Semanal'}} — R$${preco[p.key].preco.toFixed(2)}`,
                    inline: true
                });
            }
        }

        const author = {
            name: this.client.user.username,
            iconURL: this.client.user.displayAvatarURL({ dynamic: true })
        };

        return new EmbedBuilder()
            .setTitle('🛒 Sistema de Compras')
            .setColor('#00BFFF')
            .setAuthor(author)
            .setDescription(`👋 Olá, ${this.user.username}! Escolha um plano abaixo para continuar:`)
            .addFields(fields)
            .components([this._buildPlanButtonRow()]);
    }

    /**
     * Monta a row de botões de seleção de plano.
     * @private
     */
    _buildPlanButtonRow() {
        const row = new ActionRowBuilder();

        const plans = [
            { key: 'mensal',   customId: '30DiasCart' },
            { key: 'quizena',  customId: '15DiasCart' },
            { key: 'semanal',  customId: '7DiasCart' },
        ];

        for (const p of plans) {
            if (this.productData.preco[p.key]?.onoff) {
                row.addComponents(
                    new ButtonBuilder()
                        .setEmoji(`${{ [p.key]: '📅📆🗓️'[p.key] }}`)
                        .setLabel(p.label)
                        .setStyle(ButtonStyle.Primary)
                        .setCustomId(p.customId)
                );
            }
        }

        // Botão cancelar
        row.addComponents(
            new ButtonBuilder()
                .setCustomId('cancelOrder')
                .setEmoji('❌')
                .setLabel('Cancelar Pedido')
                .setStyle(ButtonStyle.Danger)
        );

        return row;
    }

    /**
     * Trata a seleção de plano via interação (botão ou força).
     * @param {Discord.Interaction|null} interaction
     * @param {string} [forcePlan]
     * @private
     */
    async _handlePlanSelection(interaction, forcePlan) {
        const targetPlan = forcePlan || (interaction?.customId ?? null);

        if (!targetPlan || !['7DiasCart', '15DiasCart', '30DiasCart'].includes(targetPlan)) return;

        let planKey;
        switch (targetPlan) {
            case '7DiasCart':   planKey = 'semanal'; break;
            case '15DiasCart':  planKey = 'quizena'; break;
            case '30DiasCart':  planKey = 'mensal';   break;
            default: return;
        }

        this.setPlan(planKey);

        // Atualiza DB
        await Cart.findOneAndUpdate(
            { channelId: this.#channel?.id },
            { quantity: this.#quantity, selectedPlan: planKey, days: this.#days, status: 'Escolhendo plano' },
            { upsert: true, new: true }
        ).catch(err => console.error('[CartClass] Falha ao salvar plano:', err));

        // Re-renderiza itens do carrinho
        await this._updateCartItemsMessage();

        // Log
        await this.sendLog('Plano Selecionado', {
            'Plano escolhido': planKey === 'mensal' ? 'Mensal (30d)' : planKey === 'quizena' ? 'Quinzenal (15d)' : 'Semanal (7d)',
            'Quantidade': this.#quantity,
            'Cart ID': this.#cartId,
            timestamp: '<t:' + Math.floor(Date.now() / 1000) + ':f> (<t:' + Math.floor(Date.now() / 1000) + ':R>)'
        });

        // Reinicia timer
        this.#startInactivityTimer();
    }

    /**
     * Atualiza o embed de itens do carrinho.
     * @private
     */
    async _updateCartItemsMessage() {
        if (!this.#channel || !this.#messageId) return;

        const { preco } = this.productData;
        const planLabel = this.#currentPlan
            ? this.#currentPlan === 'mensal' ? 'Mensal' : this.#currentPlan === 'quizena' ? 'Quinzenal' : 'Semanal'
            : '?';

        const total = Number(preco[this.#currentPlan]?.preco ?? 0 * this.#quantity).toFixed(2);

        const embed = new EmbedBuilder()
            .setTitle('🛒 Seu Carrinho')
            .setColor('#060A18')
            .setDescription(
                `Olá, ${this.user.username}!\n\n` +
                `- 📦 **Produto:** \`${this.productData.productName}\`\n` +
                `- ✨ **Plano:** ${planLabel} (×${this.#quantity}) — ~${this.#days} dias\n` +
                `- 💰 **Total:** R$${total}`
            );

        const buttons = new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId('addToCart').setLabel('+1').setStyle(ButtonStyle.Primary),
            new ButtonBuilder().setCustomId('removeFromCart').setLabel('-1').setStyle(ButtonStyle.Secondary),
            new ButtonBuilder().setCustomId('finalizePurchase').setLabel('✅ Confirmar').setStyle(ButtonStyle.Success).setEmoji('✅'),
            new ButtonBuilder().setCustomId('cancelOrder').setLabel('❌ Cancelar').setStyle(ButtonStyle.Danger).setEmoji('❌')
        );

        await this.#channel.editMessage(this.#messageId, { embeds: [embed], components: [buttons] });
    }

    /**
     * Adiciona/remove item do carrinho.
     * @param {Discord.Interaction} interaction
     * @param {'add'|'remove'} action
     */
    async handleQuantityChange(interaction, action) {
        try {
            if (action === 'add') {
                this.#quantity += 1;
            } else {
                this.#quantity -= 1;
                if (this.#quantity <= 0) {
                    this.#quantity = 1;
                    await interaction.reply({
                        embeds: [new EmbedBuilder().setDescription('❌ Quantidade mínima é 1 item.')],
                        ephemeral: true
                    });
                    return;
                }
            }

            await Cart.findOneAndUpdate(
                { channelId: this.#channel?.id },
                { quantity: this.#quantity },
                { upsert: true, new: true }
            ).catch(err => console.error('[CartClass] Erro salvando quantidade:', err));

            // Purga timer antigo e redefine
            this.#stopInactivityTimer();
            this.#startInactivityTimer();

            await interaction.update(this.#channel.url);
        } catch (error) {
            console.error('[CartClass] Erro ao alterar quantidade:', error);
        }
    }

    /**
     * Finaliza a compra → gera pagamento.
     * @param {Discord.Interaction} interaction
     */
    async finalizePurchase(interaction) {
        try {
            clearTimeout(this.#inactivityTimer);
            this.#inactivityActive = false;

            const planKey = this.#currentPlan;
            if (!planKey) {
                await interaction.reply({ content: 'Por favor, selecione um plano antes de finalizar.', ephemeral: true });
                return;
            }

            const price = Number(this.productData.preco[planKey]?.preco ?? 0);
            const totalAmount = Number(price * this.#quantity).toFixed(2);

            if (Number.isNaN(totalAmount) || totalAmount <= 0) {
                await interaction.reply({ content: 'Não foi possível calcular o valor total.', ephemeral: true });
                return;
            }

            // Salva estado atual
            await Cart.findOneAndUpdate(
                { channelId: this.#channel?.id },
                { selectedPlan: planKey, days: this.#days, status: 'Finalizando Pagamento' },
                { upsert: true, new: true }
            );

            const paymentOptions = {
                amount: Number(totalAmount),
                currency: 'BRL',
                description: `Saldo — ${this.user.username}`,
                first_name: this.user.firstName || 'Cliente',
                email: this.user.email || 'cliente@nyox.tech',
                otherData: {
                    notification_url: this.#notificationUrl,
                    source: `cart-${this.#cartId}`
                }
            };

            // Cria pagamento via PaymentProcessor
            let paymentResponse;
            try {
                paymentResponse = await this.paymentProcessor.getPayment(92690421680);
            } catch (err) {
                console.error('[CartClass] Erro chamando getPayment:', err);
                await interaction.reply({ content: 'Falha ao iniciar o pagamento. Tente novamente.', ephemeral: true });
                return;
            }

            if (!paymentResponse) {
                await interaction.reply({ content: 'Não foi possível gerar o pagamento.', ephemeral: true });
                return;
            }

            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: Number(paymentResponse.amount ?? totalAmount),
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
            await payment.save();

            // Vincula ao cart
            await Cart.findOneAndUpdate(
                { channelId: this.#channel?.id },
                { paymentId: paymentResponse.id, status: 'Pago' },
                { upsert: true, new: true }
            );

            // Inicia monitoramento assíncrono do status
            this.#paymentCheckIntervalId = setInterval(async () => {
                try {
                    const status = await this.paymentProcessor.checkPaymentStatus(paymentResponse.id);
                    if (!status) status = 'pending'; // fallback conservador

                    console.log(`[Payment] Status do pagamento ${paymentResponse.id}: ${status}`);

                    if (status === 'approved') {
                        this.#clearPaymentCheck();
                        await this.handleApprovedPayment(paymentResponse.id);
                    } else if (status === 'cancelled') {
                        this.#clearPaymentCheck();
                        await this.handleCancellationViaPayment(interaction);
                    }
                    // 'expired', 'failed', etc. podem ser tratados conforme necessidade
                } catch (err) {
                    console.error('[Payment] Erro no check de status:', err);
                }
            }, this.#paymentCheckIntervalMs);

            // Mostra resumo + opções
            await interaction.deferUpdate();

            const attachment = paymentResponse.attachment ?? null;
            const pixCode = paymentResponse.pixCopyPasteCode ?? '';

            const summaryEmbed = new EmbedBuilder()
                .setTitle('🛒 Resumo do Pedido')
                .setColor('#06CC71')
                .setDescription(
                    `📨 **ID do Carrinho:** \`${this.#cartId}\`\n` +
                    `📦 **Produto:** \`${this.productData.productName}\`\n` +
                    `✨ **Plano:** ${this.#currentPlan === 'mensal' ? 'Mensal' : this.#currentPlan === 'quizena' ? 'Quinzenal' : 'Semanal'}} (×${this.#quantity})\n` +
                    `💸 **Total:** R$${totalAmount}`
                );

            if (attachment) {
                summaryEmbed.setImage(`attachment://${paymentResponse.id}`);
            }

            const optionsRow = new ActionRowBuilder().addComponents(
                new ButtonBuilder()
                    .setCustomId('pixCopyPaste')
                    .setLabel('💰 Copiar Código Pix')
                    .setEmoji('📱')
                    .setStyle(ButtonStyle.Secondary),
                new ButtonBuilder()
                    .setCustomId('qrCode')
                    .setLabel('🖥️ Ver QR Code')
                    .setStyle(ButtonStyle.Secondary),
                new ButtonBuilder()
                    .setCustomId('cancelPayment')
                    .setLabel('Cancelar Pedido')
                    .setStyle(ButtonStyle.Danger)
            );

            await this.#channel.send({
                embeds: [summaryEmbed],
                components: [optionsRow]
            });

            // Responde com detalhes do pagamento (se necessário)
            if (pixCode) {
                await interaction.reply({ content: `Código Pix:\n\`\`\`text\n${pixCode}\n\`\`\``, ephemeral: true });
            }

        } catch (error) {
            console.error('[CartClass] Erro ao finalizar pedido:', error);
            await interaction.reply({ content: 'Ocorreu um erro ao processar seu pedido. Tente novamente.', ephemeral: true });
        }
    }

    /**
     * Lida com pagamento aprovado.
     * @param {object} paymentResponse
     */
    async handleApprovedPayment(paymentResponse) {
        try {
            const cart = await Cart.findOne({ channelId: this.#channel?.id });
            if (!cart || cart.status !== 'Finalizando Pagamento') return;

            cart.status = 'Pago';
            await cart.save();

            const member = this.interaction?.guild?.members?.cache?.get(this.user.id);
            if (member) {
                try {
                    await member.roles.add(this.#approvedRoleId).catch(() => console.log('Já possui o cargo.'));
                } catch (err) {
                    console.warn('[CartClass] Falha ao adicionar cargo:', err.message);
                }
            }

            // Limpa mensagens antigas do canal (mantém só a mensagem final)
            try {
                await this.#channel.bulkDelete(Math.ceil((await this.#channel.messages.count()) - 1));
            } catch (_) { /* ignore */ }

            await this.#channel.send({
                content: `✅ **Pagamento Aprovado!**\n🆔 **ID da Compra:** \`${this.#cartId}\``
            });

            await this.#channel.send({
                embeds: [
                    new EmbedBuilder()
                        .setTitle('🎉 Compra Concluída!')
                        .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                        .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                        .setDescription(
                            `Parabéns, **${this.user.username}**! Sua compra foi concluída com sucesso.\n\n` +
                            `Para receber sua aplicação, por favor preencha as informações solicitadas no próximo passo.`
                        )
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder().setLabel('🎉 Enviar Bot').setEmoji('🚀').setStyle(ButtonStyle.Success).setCustomId(`redeemBot_${this.#cartId}`),
                        new ButtonBuilder().setLabel('🤖 Portal Desenvolvedor').setEmoji('🌐').setStyle(ButtonStyle.Link).setURL('https://discord.com/developers/applications/'),
                        new ButtonBuilder().setLabel('🔗 Tutorial').setEmoji('📖').setStyle(ButtonStyle.Link).setURL('https://docs.nyox.tech/tutorials/createapp')
                    )
                ]
            });

            console.log(`[CartClass] Pagamento aprovado para ${this.user.username}`);
        } catch (error) {
            console.error('[CartClass] Erro ao tratar pagamento aprovado:', error);
        }
    }

    /**
     * Cancela a ordem inteira (por usuário ou sistema).
     * @param {Discord.Interaction} interaction
     */
    async handleCancellation(interaction) {
        try {
            // Para evitar double-cancel, verifica se já foi deletado
            if (this.#channel && (await this.#channel.delete()).then(() => {}).catch(() => false)) {
                return; // já deletado
            }

            const logEmbed = new EmbedBuilder()
                .setTitle('🗑️ Sistema de Logs')
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild.name, iconURL: this.interaction.guild.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.username} - \`${this.user.id}\`, inline: false },
                    { name: '📝 Ação', value: `Encerrou carrinho — \`${this.#cartId}\``, inline: false },
                    { name: '🕒 Data/Hora', value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false },
                    { name: '❔ Motivo', value: 'Cancelado pelo usuário', inline: false }
                );

            await this.sendLog('Cancelamento', { motivo: 'Pedido cancelado pelo usuário' });

            // Remove pagamento vinculado (se houver)
            const paidCart = await Cart.findOne({ channelId: this.#channel?.id });
            if (paidCart?.paymentId) {
                try {
                    await this.paymentProcessor.cancelPayment(paidCart.paymentId).catch(() => {});
                } catch (err) {
                    console.warn('[CartClass] Aviso: não foi possível cancelar pagamento diretamente:', err.message);
                }
            }

            if (this.#channel) {
                await Cart.deleteOne({ channelId: this.#channel.id }).catch(() => {});
                await this.#channel.delete();
            }

            // Notifica o usuário
            if (this.interaction) {
                await this.interaction.reply({
                    content: '❌ Pedido cancelado com sucesso. Se precisar recomeçar, basta interagir novamente com o produto.',
                    ephemeral: true
                });
            }
        } catch (error) {
            console.error('[CartClass] Erro ao cancelar pedido:', error);
        }
    }

    /**
     * Cancela pagamento específico (chamado do botão dentro do fluxo de pagamento).
     * @param {Discord.Interaction} interaction
     */
    async handleCancelPayment(interaction) {
        try {
            const cart = await Cart.findOne({ channelId: this.#channel?.id });
            const paymentId = cart?.paymentId;

            if (!paymentId) {
                await this.handleCancellation(interaction);
                return;
            }

            await this.paymentProcessor.cancelPayment(paymentId).catch(err => console.warn('[Payment] Cancelamento falhou:', err));

            if (this.#channel) {
                await Cart.deleteOne({ channelId: this.#channel.id }).catch(() => {});
                await this.#channel.delete().catch(() => {});
            }

            if (this.interaction) {
                await this.interaction.reply({ content: '❌ Pedido cancelado.', ephemeral: true });
            }
        } catch (error) {
            console.error('[CartClass] Erro ao cancelar pagamento:', error);
        }
    }

    // ---------------------------------------------------------------
    // Fluxo principal (usado via run() no main.js)
    // ---------------------------------------------------------------

    /**
     * Coletores de componentes dentro do canal do carrinho.
     * @param {Discord.GuildChannel} channel
     */
    async startCollector(channel) {
        if (!channel) throw new Error('Canal do carrinho não disponível.');

        const collector = channel.createMessageComponentCollector({
            componentType: ComponentType.Button,
            time: 600_000 // 10 minutos
        });

        collector.on('collect', async (btnInteraction) => {
            // Segurança: apenas o dono pode interagir
            if (btnInteraction.user.id !== this.user.id) {
                btnInteraction.deferUpdate();
                return;
            }

            this.#stopInactivityTimer();
            this.#startInactivityTimer();

            try {
                switch (btnInteraction.customId) {
                    case '30DiasCart':
                    case '15DiasCart':
                    case '7DiasCart':
                        await btnInteraction.deferUpdate();
                        await this._handlePlanSelection(btnInteraction, btnInteraction.customId);
                        break;

                    case 'cancelOrder':
                        await this.handleCancellation(btnInteraction);
                        break;

                    case 'addToCart':
                        await this.handleQuantityChange(btnInteraction, 'add');
                        break;

                    case 'removeFromCart':
                        await this.handleQuantityChange(btnInteraction, 'remove');
                        break;

                    case 'finalizePurchase':
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case 'pixCopyPaste':
                        await this._sendPixCode(btnInteraction);
                        break;

                    case 'qrCode':
                        await this._sendQRCode(btnInteraction);
                        break;

                    case 'cancelPayment':
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    // Botão de redimir (após aprovação)
                    case 'redeemBot_*':
                        const match = btnInteraction.customId.match(/redeemBot_(.+)$/);
                        if (match) {
                            const cart = await Cart.findOne({ id: match[1] });
                            if (cart?.status === 'Pago') {
                                await btnInteraction.deferUpdate();
                                await this.#channel.send({
                                    content: `🎉 Bem-vindo(a), **${this.user.username}**! Siga o tutorial para ativar sua aplicação.`
                                });
                            } else {
                                await btnInteraction.reply({ content: 'Seu pedido ainda não foi aprovado.', ephemeral: true });
                            }
                        }
                        break;

                    default:
                        break;
                }
            } catch (error) {
                console.error('[Component] Erro no botão:', error);
                btnInteraction.deferUpdate();
            }
        });

        collector.on('end', () => {
            this.#stopInactivityTimer();
        });

        return collector;
    }

    // ---------------------------------------------------------------
    // Pix / QR helpers
    // ---------------------------------------------------------------

    async _sendPixCode(interaction) {
        try {
            const cart = await Cart.findOne({ channelId: this.#channel?.id });
            if (!cart?.paymentId) {
                await interaction.reply({ content: 'Pagamento ainda não gerado.', ephemeral: true });
                return;
            }

            const details = await this.paymentProcessor.getPayment(cart.paymentId);
            if (!details?.pixCopyPasteCode) {
                await interaction.reply({ content: 'Não foi possível obter o código Pix.', ephemeral: true });
                return;
            }

            await interaction.reply({ content: `💰 **Código Pix (copiar e colar):**\n\`\`\`text\n${details.pixCopyPasteCode}\n\`\`\``, ephemeral: true });
        } catch (error) {
            console.error('[CartClass] Erro enviando código Pix:', error);
            await interaction.reply({ content: 'Erro ao obter os dados do Pix.', ephemeral: true });
        }
    }

    async _sendQRCode(interaction) {
        try {
            const cart = await Cart.findOne({ channelId: this.#channel?.id });
            if (!cart?.paymentId) {
                await interaction.reply({ content: 'Pagamento ainda não gerado.', ephemeral: true });
                return;
            }

            const details = await this.paymentProcessor.getPayment(cart.paymentId);
            if (!details?.attachment) {
                await interaction.reply({ content: 'Não foi possível gerar o QR Code.', ephemeral: true });
                return;
            }

            await interaction.reply({ files: [details.attachment], ephemeral: true });
        } catch (error) {
            console.error('[CartClass] Erro enviando QR Code:', error);
            await interaction.reply({ content: 'Erro ao gerar o QR Code.', ephemeral: true });
        }
    }

    // ---------------------------------------------------------------
    // Timer de inatividade
    // ---------------------------------------------------------------

    #startInactivityTimer(callback) {
        if (this.#inactivityTimer) {
            clearTimeout(this.#inactivityTimer);
        }
        this.#inactivityTimer = setTimeout(callback, this.#inactivityDelayMs);
        this.#inactivityActive = true;
    }

    #stopInactivityTimer() {
        if (this.#inactivityTimer) {
            clearTimeout(this.#inactivityTimer);
            this.#inactivityTimer = null;
            this.#inactivityActive = false;
        }
    }

    // ---------------------------------------------------------------
    // Expose public API simples
    // ---------------------------------------------------------------

    /**
     * Getter público do plano atual (útil para logs externos).
     * @returns {'mensal'|'quizena'|'semanal'|null}
     */
    get currentPlan() { return this.#currentPlan; }

    /**
     * Setter público do plano (uso controlado).
     * @param {'mensal'|'quizen'|'semanal'} val
     */
    set plan(val) { this.setPlan(val); }

    /**
     * Pega o ID do canal interno.
     * @returns {string|null}
     */
    get channel() { return this.#channel?.id ?? null; }

    /**
     * Encerra tudo e remove o carrinho.
     */
    async destroy() {
        this.#stopInactivityTimer();
        this.clearPaymentCheck();

        if (this.#channel) {
            const cart = await Cart.findOne({ channelId: this.#channel.id });
            if (cart?.paymentId) {
                try { await this.paymentProcessor.cancelPayment(cart.paymentId).catch(() => {}); }
                catch (_) { /* ignore */ }
            }
            await Cart.deleteOne({ channelId: this.#channel.id }).catch(() => {});
            await this.#channel.delete().catch(() => {});
        }
    }
}

module.exports = CartClass;
