---

## 2. Arquivo JavaScript (`js/login.js`)

```javascript
const SERVER = 'ws://localhost:8080'; // ajuste conforme seu servidor
let ratchet = null;

function iniciarChat() {
    ratchet = new Ratchet('chatAlura', {
        serverUrl: SERVER,
        connectionType: 'websocket'
    });

    ratchet.on('connection_opened', () => {
        document.getElementById('log').innerHTML += '<div class="success">✅ Conectado!</div>';
    });

    ratchet.on('message_received', (data) => {
        const msgDiv = document.createElement('div');
        msgDiv.textContent = `📩 ${JSON.parse(data.data).sender || ''}: ${JSON.parse(data.data).text}`;
        document.getElementById('log').appendChild(msgDiv);
        document.getElementById('log').scrollTop = document.getElementById('log').scrollHeight;
    });

    ratchet.connect();
}

document.getElementById('btnLogin').addEventListener('click', async () => {
    const senha = document.getElementById('senha').value.trim();
    const btn = document.getElementById('btnLogin');

    if (!senha) {
        alert('Por favor, digite a senha.');
        return;
    }

    btn.disabled = true;
    btn.textContent = 'Entrando...';

    try {
        // Primeiro, pede permissão de autenticação
        await ratchet.send({ type: 'auth_request' });

        // Aguarda resposta do servidor
        const response = await ratchet.receive({ timeout: 5000 });

        const data = JSON.parse(response.data);

        if (data.type === 'auth_success') {
            iniciarChat();
            document.getElementById('log').innerHTML += '<div class="success">Senha correta! 🎉</div>';
        } else if (data.type === 'auth_failed') {
            alert('❌ Senha incorreta. Tente outra.');
            document.getElementById('senha').value = '';
        } else if (data.type === 'not_authenticated') {
            alert('⚠️ Ainda não autenticado. Envie "authenticate" novamente.');
        }
    } catch (err) {
        alert('Erro ao se conectar ao servidor.');
        console.error(err);
    } finally {
        btn.disabled = false;
        btn.textContent = 'Entrar';
    }
});
```

---

## 3. Ajustes no PHP (`ChatController.php`)

Você precisa adaptar o PHP para responder às mensagens de autenticação enviadas pelo frontend. Uma forma simples é usar um evento customizado via `onMessage` já existente, mas o ideal é separar a lógica de login em outro arquivo ou usar um middleware. Aqui vai a versão ajustada:

```php
<?php

namespace Alura\Chat;

use Ratchet\ConnectionInterface;
use Ratchet\RFC6455\Messaging\MessageInterface;
use Ratchet\WebSocket\MessageComponentInterface;
use Ds\Set;

class ChatController implements MessageComponentInterface
{
    private Set $connections;
    private array $authenticatedUsers;

    const PASSWORD = 'senha123';  // ⚠️ Em produção, use hash + validação real

    public function __construct()
    {
        fwrite(STDOUT, 'Servidor inicializado' . PHP_EOL);
        $this->connections = new Set();
        $this->authenticatedUsers = [];
    }

    function onOpen(ConnectionInterface $conn)
    {
        fwrite(STDOUT, 'Nova conexão aberta: ' . $conn->resourceId . PHP_EOL);
        $this->connections->add($conn);
        // Envia pedido de autenticação pro cliente
        $conn->send(json_encode(['type' => 'auth_request']));
    }

    function onClose(ConnectionInterface $conn)
    {
        fwrite(STDOUT, $conn->resourceId . ' fechando conexão...' . PHP_EOL);
        $this->connections->remove($conn);
        if (($key = array_search($conn->resourceId, $this->authenticatedUsers)) !== false) {
            unset($this->authenticatedUsers[$key]);
        }
    }

    function onError(ConnectionInterface $conn, \Exception $e)
    {
        fwrite(STDERR, sprintf('Erro %s na conexão %d%s', $e->getTraceAsString(), $conn->resourceId, PHP_EOL));
    }

    public function onMessage(ConnectionInterface $from, MessageInterface $msg)
    {
        $data = json_decode($msg->getPayload(), true);

        // --- Fluxo de Autenticação ---
        if (isset($data['type']) && $data['type'] === 'authenticate') {
            if (isset($data['password']) && $data['password'] === self::PASSWORD) {
                $this->authenticatedUsers[] = $from->resourceId;
                $from->send(json_encode(['type' => 'auth_success']));
                fwrite(STDOUT, 'Usuário autenticado: ' . $from->resourceId . PHP_EOL);
                return;
            }
            $from->send(json_encode(['type' => 'auth_failed']));
            fwrite(STDOUT, 'Autenticação falhou: ' . $from->resourceId . PHP_EOL);
            return;
        }

        // --- Se chegou sem autenticar ---
        if (!in_array($from->resourceId, $this->authenticatedUsers)) {
            $from->send(json_encode(['type' => 'not_authenticated']));
            return;
        }

        // --- Enviar mensagem pro chat ---
        /** @var ConnectionInterface $connection */
        foreach ($this->connections as $connection) {
            if ($connection->resourceId !== $from->resourceId) {
                $connection->send($msg);
            }
        }
    }
}
```

---

## 4. Como Rodar

### Servidor PHP + WebSocket (exemplo com php-websocket):

```bash
cd /projetos/alura-chat
composer require vichy/evenstream ^2.0   # ou use php-websocket
php-server.php                            # depende da sua ferramenta
```

Se estiver usando **php-websocket**, o setup típico é:

```php
// websocket.php
require 'vendor/autoload.php';

use Ratchet\Server\IoS\WebSocketServer;
use Ratchet\Server\IoS\WsAcceptorInterface;
use Alura\Chat\ChatController;

$server = new WebSocketServer('ws://localhost:8080', [
    'acceptClass' => WsAcceptorInterface::class,
]);

$controller = new ChatController();
$server->register($controller);
$server->start();
```

### No navegador:

Abra `http://seu-projeto/index.html` e digite **senha123**.

---

